<?php $layout='layouts.app'; use App\Components\Breadcrumb; use App\Components\Button; $days=[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday']; $grid=[]; foreach($entries as $e)$grid[(int)$e['day_of_week'].':'.(int)$e['period_id']]=$e; ?>
<?= Breadcrumb::render([['label'=>'Timetable','href'=>'/timetable'],['label'=>$timetable['name']]]) ?>
<div class="page-header"><div><h1><?= e($timetable['name']) ?></h1><div class="subtitle"><?= e($timetable['academic_year_name'].' · '.$timetable['term_name']) ?> · <?= e(ucfirst($timetable['status'])) ?></div></div><div style="display:flex;gap:var(--space-2)"><form method="POST" action="/timetable/<?= $timetable['id'] ?>/generate"><?= csrf() ?><?= Button::primary('Generate timetable',type:'submit') ?></form><form method="POST" action="/timetable/<?= $timetable['id'] ?>/publish"><?= csrf() ?><?= Button::outline('Publish',type:'submit') ?></form><form method="POST" action="/timetable/<?= $timetable['id'] ?>/clear"><?= csrf() ?><?= Button::outline('Clear',type:'submit') ?></form></div></div>
<div class="card" style="margin-bottom:var(--space-5)"><div class="card-body"><form method="GET" action="/timetable/<?= $timetable['id'] ?>" class="form-row"><label>Class<select class="form-control" name="class_id"><option value="0">All classes</option><?php foreach($classes as $c): ?><option value="<?= $c['id'] ?>" <?= $classId===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label><label>Stream<select class="form-control" name="stream_id"><option value="">All streams</option><?php foreach($streams as $s): ?><option value="<?= $s['id'] ?>" <?= $streamId===(int)$s['id']?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach; ?></select></label><?= Button::outline('Filter',type:'submit') ?></form></div></div>
<div class="card" style="overflow:auto"><div class="card-body"><table class="table"><thead><tr><th>Period</th><?php foreach($days as $d): ?><th><?= $d ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($periods as $p): ?><tr><td><strong><?= e($p['name']) ?></strong><br><small><?= e(substr((string)$p['starts_at'],0,5).'–'.substr((string)$p['ends_at'],0,5)) ?></small></td><?php foreach($days as $d): $e=$grid[$d.':'.$p['id']]??null; ?><td style="min-width:180px"><?php if((int)$p['is_break']): ?><span class="subtitle">Break</span><?php elseif($e): ?><strong><?= e($e['subject_name']) ?></strong><br><small><?= e($e['class_name'].($e['stream_name']?' · '.$e['stream_name']:'')) ?></small><br><small><?= e($e['teacher_name']) ?></small><?php else: ?><span class="subtitle">Free</span><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></div>
<div class="card" style="margin-top:var(--space-5)"><div class="card-body"><h2>Manual lesson</h2><form method="POST" action="/timetable/<?= $timetable['id'] ?>/entries"><?= csrf() ?><div class="form-row"><label>Class<select class="form-control" name="class_id" required><?php foreach($classes as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></label><label>Teacher<select class="form-control" name="teacher_id" required><?php foreach($teachers as $t): ?><option value="<?= $t['id'] ?>"><?= e($t['first_name'].' '.$t['last_name']) ?></option><?php endforeach; ?></select></label><label>Subject<select class="form-control" name="subject_id" required><?php foreach($subjects as $s): ?><option value="<?= $s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></label></div><div class="form-row"><label>Day<select class="form-control" name="day_of_week"><?php foreach($days as $d=>$label): ?><option value="<?= $d ?>"><?= $label ?></option><?php endforeach; ?></select></label><label>Period<select class="form-control" name="period_id"><?php foreach($periods as $p): ?><?php if(!(int)$p['is_break']): ?><option value="<?= $p['id'] ?>"><?= e($p['name']) ?></option><?php endif; ?><?php endforeach; ?></select></label><label>Stream<select class="form-control" name="stream_id"><option value="">None</option><?php foreach($streams as $s): ?><option value="<?= $s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></label></div><div style="margin-top:var(--space-4)"><?= Button::primary('Add lesson',type:'submit') ?></div></form></div></div>
